import{_ as s,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"07 | K8s极简实战（二）：如何为业务选择最适合的工作负载类型？","description":"","frontmatter":{},"headers":[{"level":2,"title":"工作负载类型","slug":"工作负载类型","link":"#工作负载类型","children":[{"level":3,"title":"ReplicaSet","slug":"replicaset","link":"#replicaset","children":[]},{"level":3,"title":"Deployment","slug":"deployment","link":"#deployment","children":[]},{"level":3,"title":"StatefulSet","slug":"statefulset","link":"#statefulset","children":[]},{"level":3,"title":"DaemonSet","slug":"daemonset","link":"#daemonset","children":[]},{"level":3,"title":"Job/CronJob","slug":"job-cronjob","link":"#job-cronjob","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生架构与GitOps实战/07｜K8s极简实战（二）：如何为业务选择最适合的工作负载类型？.md","filePath":"云原生架构与GitOps实战/07｜K8s极简实战（二）：如何为业务选择最适合的工作负载类型？.md","lastUpdated":1795538134000}'),l={name:"云原生架构与GitOps实战/07｜K8s极简实战（二）：如何为业务选择最适合的工作负载类型？.md"};function i(t,a,o,c,d,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_07-k8s极简实战-二-如何为业务选择最适合的工作负载类型" tabindex="-1">07 | K8s极简实战（二）：如何为业务选择最适合的工作负载类型？ <a class="header-anchor" href="#_07-k8s极简实战-二-如何为业务选择最适合的工作负载类型" aria-label="Permalink to &quot;07 | K8s极简实战（二）：如何为业务选择最适合的工作负载类型？&quot;">​</a></h1><p>你好，我是王炜。</p><p>上一节课，我带你认识了 K8s 资源的逻辑隔离机制，也就是命名空间。它可以帮助我们更好地组织 K8s 资源，同时具有一定的隔离特性。</p><p>工作负载是 K8s 运行的业务程序。还记得我们在上一模块说 K8s 的最小调度单位是 Pod 吗？虽然工作负载类型有好几种，但他们最终都是以 Pod 的形式运行的。当然，Pod 也是一种工作负载类型，不过我们之前有提到过，在实际的项目中，我们并不会直接使用 Pod 这个工作负载类型，而是通过其他的工作负载类型来间接使用它。</p><p>这节课，我们就来看看有哪些 K8s 常用的工作负载类型，以及如何使用它们。我仍然从示例应用出发，重点向你介绍 Deployment 工作负载，只要你掌握它，就可以满足工作中常见的业务场景。</p><p>在正式开始之前，你还是需要确保已经按照“示例应用介绍”的引导在本地 Kind 集群部署了示例应用。</p><h2 id="工作负载类型" tabindex="-1">工作负载类型 <a class="header-anchor" href="#工作负载类型" aria-label="Permalink to &quot;工作负载类型&quot;">​</a></h2><p>K8s 的工作负载包括：ReplicaSet、Deployment、StatefulSet、DaemonSet、Job、CronJob。在实际工作中，我们最常用到的是 Deployment，不过在正式介绍它之前，我们首先需要先了解另外一个工作负载：ReplicaSet。</p><h3 id="replicaset" tabindex="-1">ReplicaSet <a class="header-anchor" href="#replicaset" aria-label="Permalink to &quot;ReplicaSet&quot;">​</a></h3><p>ReplicaSet 工作负载主要的作用是保持一定数量的 Pod 始终处于运行状态。当我们直接创建Pod 时，假设 Pod 所在的节点出现故障，除非手动重新创建它，否则 Pod 永远不会恢复。Pod 不具备自动恢复能力，这也是我们不推荐直接使用 Pod 的重要原因。</p><p>所以，我们需要更高维度的工作负载帮我们创建和维护 Pod，ReplicaSet 可以确保处于运行状态的 Pod 始终保持在期望的数量，让我们不必再需要担心突发故障导致的业务中断。ReplicaSet 和 Pod 的关系如图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/07/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/07/1.png" alt=""></a></p><p>为了进一步说明 ReplicaSet 的特性，接下来，我们尝试创建 ReplicaSet 工作负载。先将下面的内容保存为 ReplicaSet.yaml：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: ReplicaSet</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: frontend</span></span>
<span class="line"><span> labels:</span></span>
<span class="line"><span>   app: frontend</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> replicas: 3   # 3 个副本数</span></span>
<span class="line"><span> selector:</span></span>
<span class="line"><span>   matchLabels:</span></span>
<span class="line"><span>     app: frontend</span></span>
<span class="line"><span> template:</span></span>
<span class="line"><span>   metadata:</span></span>
<span class="line"><span>     labels:</span></span>
<span class="line"><span>       app: frontend</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     containers:</span></span>
<span class="line"><span>     - name: frontend</span></span>
<span class="line"><span>       image: lyzhang1999/frontend:v1</span></span></code></pre></div><p>然后，使用 kubectl apply 创建 ReplicaSet 工作负载：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl apply -f ReplicaSet.yaml</span></span>
<span class="line"><span>replicaset.apps/frontend created</span></span></code></pre></div><p>现在，我们尝试修改 ReplicaSet.yaml 的内容，将镜像版本从 v1 修改到 v2：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: ReplicaSet</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: frontend</span></span>
<span class="line"><span> ......</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> ......</span></span>
<span class="line"><span> template:</span></span>
<span class="line"><span>   ......</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     containers:</span></span>
<span class="line"><span>     - name: frontend</span></span>
<span class="line"><span>       image: lyzhang1999/frontend:v2 # 修改镜像版本</span></span></code></pre></div><p>再次运行 kubectl apply -f 使修改生效：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl apply -f ReplicaSet.yaml</span></span>
<span class="line"><span>replicaset.apps/frontend configured</span></span></code></pre></div><p>然后，我们使用 kubectl get pods 来查看所有 Pod 的镜像版本信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl get pods --selector=app=frontend -o jsonpath=&#39;{.items[*].spec.container</span></span>
<span class="line"><span>lyzhang1999/frontend:v1 lyzhang1999/frontend:v1 lyzhang1999/frontend:v1</span></span></code></pre></div><p>从返回结果可以看出，Pod 的镜像版本并没有被更新为 v2。这是因为 ReplicaSet 只负责维护Pod 数量，在数量没有变化的情况下，Pod 不会被更新。只有将旧的 Pod 杀死，ReplicaSet才会在重新创建 Pod 的时候使用新的镜像版本。</p><p>要验证这个过程，你可以使用 kubectl delete pod 来删除某一个 Pod：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pods</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             READY   </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATUS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RESTARTS   AGE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">25kf4   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     Running   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          28s</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">j94fv   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     Running   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          28s</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mbst5   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     Running   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          28s</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pods frontend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">25kf4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pod </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;frontend-25kf4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deleted</span></span></code></pre></div><p>删除其中一个 Pod 之后，ReplicaSet 会发现 Pod 数量和预期数量相差 1 个 Pod，所以会重新创建一个 Pod 以满足预期要求。此时，我们再次查看所有 Pod 的镜像版本信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl get pods --selector=app=frontend -o jsonpath=&#39;{.items[*].spec.container</span></span>
<span class="line"><span>lyzhang1999/frontend:v2 lyzhang1999/frontend:v1 lyzhang1999/frontend:v1</span></span></code></pre></div><p>就可以从返回结果看出，Pod 重新创建后，镜像版本也随之更新了。</p><p>通过这个实验我们得出结论，ReplicaSet 只能确保 Pod 数量，在我们需要更新 Pod 的时候，并不能帮我们自动进行更新，这意味着无法实现期望状态和实际的状态的一致性。所以，在实际项目中，我们不会直接使用 ReplicaSet 工作负载，而是会使用更上层的 Deployment 工作负载。</p><h3 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h3><p>Deployment 是众多工作负载类型中最重要、也是 K8s 里最常用的工作负载类型。在实际项目中，Deployment 工作负载能够满足绝大多数的业务诉求。</p><p>Deployment 可以看作是管理 ReplicaSet 的工作负载，就像 ReplicaSet 管理 Pod 一样，它可以创建、删除 ReplicaSet，而它对 ReplicaSet 的管理最终又会影响到 Pod。Deployment、ReplicaSet 和 Pod 三者的关系如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/07/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/07/2.png" alt=""></a></p><p>Deployment 非常有用，它可以实现更新、回滚和横向扩容。比如，在我们第一次部署了 Pod之后，当需要更新 Pod 的镜像时，Deployment 可以通过不停机的滚动更新，避免旧的 Pod被同时关闭，防止服务停机。从上面这张架构图可以看出，滚动更新是通过创建多个ReplicaSet 实现的。</p><p>此外，Deployment 还可以提供横向伸缩能力，配合 HPA 自动进行扩缩容。</p><p>所以，在实际项目中，对于无状态应用，Deployment 是最佳的选择。在我们这个示例应用中，前后端以及数据库都是采用 Deployment 工作负载部署的，如果你在实际工作中需要使用它，也可以参考示例中的写法。Deployment 的字段和 Pod 比较相似，这里就不再为你一一介绍了。</p><p>接下来，我将以示例应用为例，带你进一步理解 Deployment 是如何管理 ReplicaSet 的。</p><p>在开始之前，请确认你已经按照“示例应用介绍”将演示应用部署到了 example 命名空间。</p><p>确认好之后，我们使用 kubectl describe deployment 来获取工作负载详情：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl describe deployment backend -n example</span></span>
<span class="line"><span>Name:                   backend</span></span>
<span class="line"><span>Namespace:              example</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>Replicas:               2 desired | 2 updated | 2 total | 2 available | 0 unavail</span></span>
<span class="line"><span>StrategyType:           RollingUpdate</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>RollingUpdateStrategy:  25% max unavailable, 25% max surge</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>OldReplicaSets:  &lt;​none&gt;</span></span>
<span class="line"><span>NewReplicaSet:</span></span>
<span class="line"><span>backend-648ff85f48 (2/2 replicas created)</span></span></code></pre></div><p>在上面的返回内容中，我们要重点关注几个信息。首先， StrategyType 代表的是部署策略，它默认以 RollingUpdate 也就是滚动更新的方式对 Pod 进行逐个更新，它是默认的更新策略，不会造成业务停机。</p><p>RollingUpdateStrategy 是对滚动更新更加精细的控制。max surge 用来指定最大超出期望Pod 的个数，max unavailable 是允许 Pod 不可用的数量，以期望 8 个副本数的工作负载为例，max unavailable 的值为 25% ，也就是 2，max surge 的值为 25%，也是 2，那么在滚动更新时，更新策略是：</p><ul><li><p>更新期间最多会有 10 个 Pod（8 个所需的 Pod + 2 个 maxSurge Pod）处于运行状态；</p></li><li><p>更新期间至少会有 6 个 Pod（8 个所需的 Pod - 2 个 maxUnavailable Pod）处于运行状态。</p></li></ul><p>工作负载明细里的最后一行的 NewReplicaSet 指的是由 Deployment 创建并管理的ReplicaSet 名称。</p><p>为了更加直观地展示他们之间的关系，我们可以尝试更新 Deployment。先将我们之前部署的frontend HPA 最小 Pod 数量调整为 3，你可以使用 kubectl patch hpa 命令来调整：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl patch hpa backend -p &#39;{&quot;spec&quot;:{&quot;minReplicas&quot;: 3}​}&#39; -n example</span></span>
<span class="line"><span>horizontalpodautoscaler.autoscaling/backend patched</span></span></code></pre></div><p>在正式修改 Deployment 之前，我们先使用 kubectl get replicaset --watch 来监控 ReplicaSet的变化状态，以便进一步的分析：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl get replicaset --watch -n example</span></span>
<span class="line"><span>NAME                  DESIRED   CURRENT   READY   AGE</span></span>
<span class="line"><span>backend-648ff85f48    3         3         3       24h</span></span>
<span class="line"><span>frontend-7b55cc5c67   2         2         2       24h</span></span>
<span class="line"><span>postgres-7745b57d5d   1         1         1       24h</span></span></code></pre></div><p>打开一个新的命令行终端，使用 kubectl set image 来更新 backend Deployment：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl set image deployment/backend flask-backend=lyzhang1999/backend:v1 -n ex</span></span>
<span class="line"><span>NAME                  DESIRED   CURRENT   READY   AGE</span></span>
<span class="line"><span>backend-648ff85f48    3         3         3       25h</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>backend-6bf7dbbdbb    3         3         3       44s</span></span>
<span class="line"><span>backend-648ff85f48    0         0         0       25h</span></span></code></pre></div><p>返回结果比较多，这里只截取了一部分。从最后返回的结果可以看出，旧的 ReplicaSetbackend-648ff85f48 期望的副本数从 3 降到了 0，新创建的 ReplicaSet backend-6bf7dbbdbb最后的副本数为 3，在滚动更新的过程中，新旧 ReplicaSet 同时存在，旧的 ReplicaSet 副本数在不断减少，新的 ReplicaSet 在不断地增加。</p><p>现在，我们结合 RollingUpdateStrategy 配置中的 maxSurge 和 maxUnavailable 来分析整个滚动更新的过程：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/07/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/07/3.png" alt=""></a></p><p>在上面的图中，绿色方块表示处于就绪状态的 Pod，红色方块表示处于未就绪状态的 Pod，上方从左到右的轴线是时间轴。在 Deployment 滚动更新的过程中，旧的 ReplicaSet 不断控制Pod 缩容，新的 ReplicaSet 不断控制 Pod 扩容，在某个时间点，新旧 ReplicaSet 会共存。</p><p>有了滚动更新的机制，我们再也不用担心因为发布导致的业务中断问题了。</p><p>如果你需要把业务迁移到 K8s，尤其是对于现代微服务应用，你应该将 Deployment 工作负载作为首选类型。</p><h3 id="statefulset" tabindex="-1">StatefulSet <a class="header-anchor" href="#statefulset" aria-label="Permalink to &quot;StatefulSet&quot;">​</a></h3><p>StatefulSet 和 Deployment 工作负载非常类似，但它主要用于部署“有状态”的应用，它的核心能力是保存 Pod 的状态，比如最常见的如存储状态。在出现故障 Pod 需要重建时，新的 Pod将恢复原来的状态。</p><p>在实际工作中，StatefulSet 主要解决以下两个问题。</p><ul><li><p>副本之间有差异：相比较 Deployment 那样创建完全一致的 Pod 副本，StatefulSet 面向的场景会更复杂。例如一些中间件场景需要有主从节点，它会要求先启动主节点 Pod ，再启动从节点 Pod，StatefulSet 就可以很好地完成这类操作。此外，当 Pod 出现异常需要重建时，StatefulSet 可以确保 Pod 的名称一致性。</p></li><li><p>保持存储状态：StatefulSet 可以配合持久化存储一起使用，即便是 Pod 被删除，StatefulSet 仍然能够通过绑定关系找到持久化存储卷。</p></li></ul><p>在实际的业务场景里，StatefulSet 经常用来部署中间件，例如 Postgres、MySQL、MongoDB、etcd 等。这些中间件有时候需要以主从的方式进行高可用部署，StatefulSet 为这些组件提供了很好的支持。</p><p>实际上，我们在工作中几乎不会以 StatefulSet 的形式部署业务系统。在一些特殊的环境下，比如 Demo 和测试环境，业务应用可能会需要数据库或者 MQ 消息队列，此时则需要使用StatefulSet 工作负载。即便是使用这些数据库和 MQ 等中间件，我们也不需要自己写StatefulSet Manifest，只需要找到对应中间件的 Helm Chart 直接安装即可。</p><p>最后我想说的是，在生产环境中，我并不推荐你使用 StatefulSet 来部署这些中间件，这是因为诸如数据库和消息队列中间件，除了需要持久化以外，还需要实现数据备份和容灾，这并不是 K8s 擅长的，也没必要重复造轮子。</p><p>对于常用的中间件，云厂商都为我们提供了对应的高可用产品。例如 MySQL 数据库实例，它们底层支持高可用，按量付费，并且几乎不需要付出额外的维护成本，直接使用它们是一种更好的技术选型方案。</p><h3 id="daemonset" tabindex="-1">DaemonSet <a class="header-anchor" href="#daemonset" aria-label="Permalink to &quot;DaemonSet&quot;">​</a></h3><p>DaemonSet 是一种非常特殊的工作负载，你可以把它理解为节点级的守护进程，它可以为集群的每个节点都创建一个 Pod。当节点被添加时，它会在新节点启动新的 Pod，相反地，当节点被删除时，Pod 也将会被删除。</p><p>DaemonSet 经常用于下面几种业务场景。</p><ul><li><p>存储插件：在每一个节点运行存储守护进程，例如 Ceph。</p></li><li><p>网络插件代理：在每一个节点上运行网络插件，以便处理节点的容器网络通信。</p></li><li><p>监控和日志组件：为每一个节点采集日志或者监控指标，例如 Prometheus Node Exporter和 Fluentd。</p></li></ul><p>从这些业务场景里我们会发现，DaemonSet 一般用来扩展 K8s 的能力，比如日志和监控组件，这些都是我们经常会使用的。和 StatefulSet 类似，我们在工作中也几乎不会以DaemonSet 的方式部署业务应用。</p><h3 id="job-cronjob" tabindex="-1">Job/CronJob <a class="header-anchor" href="#job-cronjob" aria-label="Permalink to &quot;Job/CronJob&quot;">​</a></h3><p>刚才我们讲到的 Deployment、StatefulSet 和 DaemonSet 都有一个特点，那就是它们都主要针对长时间运行的应用。除非发生了错误，否则 Pod 将一直运行下去。</p><p>试想有一种场景，你需要运行一个批处理任务，运行结束即代表完成任务。如果你使用Deployment 和其他的工作负载，进程结束后， K8s 会认为出现了故障，于是不断重启 Pod。这是肯定不行的。像这种一次性的任务 Job 就派上用场了。</p><p>在实际的业务场景中，我们经常会使用 Job 来处理数据库迁移任务。下面是一个典型的 JobManifest 例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: batch/v1</span></span>
<span class="line"><span>kind: Job</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: &quot;migration-job&quot;</span></span>
<span class="line"><span> labels:</span></span>
<span class="line"><span> annotations:</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> backoffLimit: 4</span></span>
<span class="line"><span> activeDeadlineSeconds: 200</span></span>
<span class="line"><span> completions: 1</span></span>
<span class="line"><span> parallelism: 1</span></span>
<span class="line"><span> template:</span></span>
<span class="line"><span>   metadata:</span></span>
<span class="line"><span>     name: &quot;migration-job-pod&quot;</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     restartPolicy: Never</span></span>
<span class="line"><span>     containers:</span></span>
<span class="line"><span>     - name: db-migrations</span></span>
<span class="line"><span>       image: rancher/gitjob:v0.1.32</span></span>
<span class="line"><span>       command: [&quot;/bin/sh&quot;, &quot;-c&quot;]</span></span>
<span class="line"><span>       args:</span></span>
<span class="line"><span>         - git clone \${DB_MIGRATION_SCRIPT_REPO} &amp;&amp; sh migrate.sh</span></span></code></pre></div><p>这段 Manifest 是一段示例内容，放在这里目的是为你提供参考，并不能真正工作。它的核心任务是启动一个包含 Git 客户端的容器，使用 git clone 命令来克隆数据库 migrate 脚本的仓库，然后运行脚本完成数据迁移。</p><p>接下来我们详细看看 Job 的一些特殊字段。</p><p>backoffLimit 代表 Job 运行失败之后重新运行的次数，默认值为 6。需要注意的是，Job 的重启时间是呈指数级增长的，例如，下一次 Job 重新运行的时间可能是 10s、20s、40s，最大时间为 6 分钟。</p><p>completions 字段表示 Job 的完成条件，默认值为 1，意味着当有一个 Pod 的状态为“完成”时，Job 也就完成了。</p><p>parallelism 字段表示并行，意思是同时启动几个 Pod 运行任务，默认值为 1 ，意味着默认只启动一个 Pod 运行任务。</p><p>restartPolicy 代表重启策略，如果我们把 restartPolicy 设置为 Never，意味着 Pod 运行失败后将不会被重新启动。除了 Never，我们还可以设置 OnFailure，意思是如果容器进程退出状态码非 0 ，那么 Pod 将会被自动重启，重新执行任务，而在 Deployment 中，restartPolicy 字段只能被设置为 Always。</p><p>当 Job 运行完成后，Pod 的状态将从 Running 转变为 Completed。但我们还可能遇到一种特殊情况，如果任务卡住或者长时间没反应怎么办呢？其实这时候我们可以使用activeDeadlineSeconds 字段控制 Pod 的最长运行时间。</p><p>在上面的配置中，如果运行时间超过 200 秒，那么 Pod 会被强制终止，并且在事件中显示的终止原因是 DeadlineExceeded。</p><p>还有一种和 Job 类似的工作负载类型是 CronJob，它们的区别在于 CronJob 可以设置和Linux Crontab 一致的表达式，并在特定的时间自动重复运行，例如每分钟自动运行一次，下面是 CronJob 的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: batch/v1</span></span>
<span class="line"><span>kind: CronJob</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: run-every-minute</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> schedule: &quot;* * * * *&quot;</span></span>
<span class="line"><span> jobTemplate:</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     template:</span></span>
<span class="line"><span>       spec:</span></span>
<span class="line"><span>         containers:</span></span>
<span class="line"><span>         - name: cronjob</span></span>
<span class="line"><span>           image: busybox:latest</span></span>
<span class="line"><span>           command:</span></span>
<span class="line"><span>           - /bin/sh</span></span>
<span class="line"><span>           - -c</span></span>
<span class="line"><span>           - echo Hello World</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在这节课，我为你介绍了 K8s 几种常见的工作负载类型。其中，Deployment 是最常用的一种工作负载，你可以多花点时间去理解它。Deployment 的功能非常强大，它可以和其他的 K8s对象一起工作，配置也相对复杂，我们还会在后续的课程中做进一步的补充。</p><p>此外，我还介绍了 Statefulset 和 DaemonSet。在实际的业务场景，我们几乎不会将业务应用以这两种工作负载的方式进行部署，所以我并没有为你进行深入介绍。不过，在 Demo 和测试场景中，业务应用要顺利运行往往还需要其他中间件的配合，例如数据库和中间件，这些中间件可以直接使用社区已经封装好的 Helm chart 进行部署，这部分内容也将在后续的课程中详细介绍。</p><p>除了上面这些针对长时间运行的应用，Job 和 CronJob 更适合处理一次性的任务，它们可以帮助你把一些批处理任务迁移到 K8s 中，比如典型的场景是数据库初始化工作以及传统的Crontab 定时任务。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，给你留一道思考题吧。</p><p>在前面 backend 滚动更新的例子中，示意图里新旧 ReplicaSet 共存期间一共有 4 个 Pod，但其实这并不准确，你能通过实践找出滚动更新过程最多有几个 Pod 同时存在吗？（提示：Terminating 终止状态也同时计入。）</p><p>欢迎你给我留言交流讨论，你也可以把这节课分享给更多的朋友一起阅读。我们下节课见。</p>`,92)])])}const g=s(l,[["render",i]]);export{k as __pageData,g as default};
